export function LocationMap(n){return`<div class="location-map-container">\n    <div class="location-map">\n      <div class="map-silhouette">\n        <svg viewBox="0 0 300 350" class="india-outline">\n          <path d="M150,20 L180,30 L210,50 L230,80 L240,110 L260,130 L270,160 L260,190 L240,210 L250,240 L240,270 L220,290 L200,310 L170,330 L140,340 L110,330 L80,310 L60,280 L50,250 L40,220 L30,190 L40,160 L50,130 L60,100 L80,70 L100,50 L120,30 Z" \n            fill="none" stroke="var(--text-secondary)" stroke-width="1" opacity="0.3"/>\n        </svg>\n      </div>\n      ${n.map(n=>`\n    <div class="location-marker" data-id="${n.id}" style="left: ${(n.coordinates.lng-68)/25*100}%; top: ${(36-n.coordinates.lat)/16*100}%;">\n      <div class="location-dot" style="background: ${n.color}"></div>\n      <div class="location-label">${n.name}</div>\n      <div class="location-tooltip">\n        <strong>${n.name}</strong><br/>\n        ${n.city}, ${n.state}<br/>\n        <small>${n.coordinates.lat.toFixed(2)}°N, ${n.coordinates.lng.toFixed(2)}°E</small>\n      </div>\n    </div>`).join("")}\n    </div>\n    <div class="location-legend">\n      <h4>Memorials</h4>\n      ${n.map(n=>`\n        <div class="legend-item" data-id="${n.id}">\n          <span class="legend-dot" style="background: ${n.color}"></span>\n          <span class="legend-name">${n.name}</span>\n          <span class="legend-coords">${n.coordinates.lat.toFixed(2)}°N, ${n.coordinates.lng.toFixed(2)}°E</span>\n        </div>`).join("")}\n    </div>\n  </div>`}